This program defines a sorted integer array, calculates the mean (rounded down), and performs a binary search on the array.

### File 1: `utils.h`
This header file declares the function prototypes so the driver and implementation files can communicate.

```c
#ifndef UTILS_H
#define UTILS_H

#include <stddef.h>

/**
 * Calculates the mean of an integer array.
 * The result is rounded down to the nearest integer.
 * 
 * @param arr The array of integers.
 * @param size The number of elements in the array.
 * @return The mean as an int (floor).
 */
int calculate_mean(const int arr[], size_t size);

/**
 * Performs a binary search on a sorted array.
 * 
 * @param arr The sorted array of integers.
 * @param size The number of elements in the array.
 * @param target The value to search for.
 * @return The index of the target if found, or -1 if not found.
 */
int binary_search(const int arr[], size_t size, int target);

#endif /* UTILS_H */
```

### File 2: `utils.c`
This file contains the logic for calculating the mean and the binary search algorithm.

```c
#include "utils.h"

int calculate_mean(const int arr[], size_t size) {
    if (size == 0) {
        return 0; // Handle empty array case gracefully
    }

    long long sum = 0; // Use long long to prevent overflow during summation
    for (size_t i = 0; i < size; i++) {
        sum += arr[i];
    }

    // Integer division in C automatically rounds down (truncates) for positive results
    return (int)(sum / size);
}

int binary_search(const int arr[], size_t size, int target) {
    size_t left = 0;
    size_t right = size - 1;

    while (left <= right) {
        size_t mid = left + (right - left) / 2; // Prevents potential overflow

        if (arr[mid] == target) {
            return (int)mid;
        } else if (arr[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    return -1; // Target not found
}
```

### File 3: `main.c`
This is the driver code. It initializes a sorted array, prints the mean, and tests the binary search with both existing and non-existing values.

```c
#include <stdio.h>
#include "utils.h"

int main(void) {
    // A sorted array of integers
    int data[] = {2, 5, 8, 12, 16, 23, 38, 45, 56, 67, 79, 90};
    size_t size = sizeof(data) / sizeof(data[0]);

    printf("Array: ");
    for (size_t i = 0; i < size; i++) {
        printf("%d ", data[i]);
    }
    printf("\n");

    // 1. Calculate Mean
    int mean = calculate_mean(data, size);
    printf("Mean (rounded down): %d\n", mean);

    // 2. Binary Search Examples
    int targets[] = {23, 100, 5, 45};

    for (int i = 0; i < 4; i++) {
        int target = targets[i];
        int index = binary_search(data, size, target);

        if (index != -1) {
            printf("Found %d at index %d\n", target, index);
        } else {
            printf("%d not found in the array\n", target);
        }
    }

    return 0;
}
```

### How to Compile and Run

You can compile these files together using a standard C compiler like `gcc`.

1.  **Save the files**: Ensure `main.c`, `utils.h`, and `utils.c` are in the same directory.
2.  **Compile**: Run the following command in your terminal:
    ```bash
    gcc main.c utils.c -o array_program
    ```
3.  **Run**:
    ```bash
    ./array_program
    ```

